import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type CartoonProgressBarProps = Record<string, any>;

const CartoonProgressBar: React.FC<CartoonProgressBarProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 5,
  barColor = "#FFD700", // Gold/Yellow
  stripeColor = "#FFA500", // Orange
  borderColor = "#000000",
  textColor = "#000000",
  label = "LOADING...",
  targetProgress = 85,
  barWidthPercent = 70,
  barHeight = 80,
  borderThickness = 6,
}) => {
  // Load specialized cartoon font
  useFontLoader(["Fredoka One"]);

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // --- Calculations ---
  
  // Handle background transparency safely
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Responsive sizing
  const containerWidth = width * (barWidthPercent / 100);
  const borderRadius = barHeight / 2; // Perfectly rounded ends for cartoon look

  // --- Animations ---

  // 1. Initial Pop-in of the whole bar container
  const entranceSpring = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
    },
  });

  // 2. Progress Bar Fill Animation (delayed slightly)
  const fillSpring = spring({
    frame: frame - 15, // Start filling after entrance
    fps,
    config: {
      damping: 20,
      stiffness: 60,
    },
  });

  // Clamp fill to target percentage
  const currentProgress = interpolate(fillSpring, [0, 1], [0, targetProgress], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // 3. Moving Stripes Animation
  // Continuous movement based on frame count
  const stripeOffset = interpolate(frame, [0, fps], [0, barHeight], {
    extrapolateRight: "extend",
  });

  // --- Styles ---

  const containerStyle: React.CSSProperties = {
    width: containerWidth,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    gap: 20,
    transform: `scale(${entranceSpring})`,
  };

  const labelStyle: React.CSSProperties = {
    fontFamily: "Fredoka One",
    fontSize: barHeight * 0.8,
    color: textColor,
    textShadow: `3px 3px 0px ${borderColor}`, // Hard cartoon shadow
    WebkitTextStroke: `1px ${borderColor}`,
    letterSpacing: "2px",
    marginBottom: 10,
  };

  const borderBoxStyle: React.CSSProperties = {
    width: "100%",
    height: barHeight,
    border: `${borderThickness}px solid ${borderColor}`,
    borderRadius: borderRadius,
    backgroundColor: "#ffffff",
    boxShadow: `${borderThickness}px ${borderThickness}px 0px 0px rgba(0,0,0,1)`, // Hard shadow
    overflow: "hidden",
    position: "relative",
  };

  const progressFillStyle: React.CSSProperties = {
    height: "100%",
    width: `${currentProgress}%`,
    backgroundColor: barColor,
    borderRight: `${borderThickness}px solid ${borderColor}`,
    // CSS Stripes Pattern
    backgroundImage: `linear-gradient(
      45deg,
      ${stripeColor} 25%,
      transparent 25%,
      transparent 50%,
      ${stripeColor} 50%,
      ${stripeColor} 75%,
      transparent 75%,
      transparent
    )`,
    backgroundSize: `${barHeight}px ${barHeight}px`, // Square tiles based on height
    backgroundPosition: `${stripeOffset}px 0`, // Animate X position
    display: "flex",
    alignItems: "center",
    justifyContent: "flex-end",
    transition: "none", // Ensure no conflict with React renders
  };

  const percentageTextStyle: React.CSSProperties = {
    fontFamily: "Fredoka One",
    color: textColor,
    fontSize: barHeight * 0.4,
    marginRight: 15,
    whiteSpace: "nowrap",
    // Only show text if bar is wide enough
    opacity: currentProgress > 15 ? 1 : 0,
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div style={containerStyle}>
        {/* Text Label */}
        {label && <div style={labelStyle}>{label}</div>}

        {/* The Progress Bar */}
        <div style={borderBoxStyle}>
          <div style={progressFillStyle}>
            {/* Percentage inside bar */}
            <span style={percentageTextStyle}>
              {Math.round(currentProgress)}%
            </span>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CartoonProgressBar;